svg.script:

(async function() {
  const urls = ["https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part1.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part2.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part3.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part4.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part5.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part6.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part7.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part8.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part9.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/Dylan-r2/Parts/part10.html"];
  try {
    const responses = await Promise.all(urls.map(u => fetch(u).then(r => {
      if(!r.ok) throw new Error("Failed to load " + u);
      return r.text();
    })));
    const fullHtml = responses.join("");
    const parsed = new DOMParser().parseFromString(fullHtml, "text/html");
    document.replaceChild(parsed.documentElement, document.documentElement);
    Array.from(parsed.querySelectorAll("script")).forEach(oldScript => {
      const newScript = document.createElement("script");
      Array.from(oldScript.attributes).forEach(attr => newScript.setAttribute(attr.name, attr.value));
      newScript.textContent = oldScript.textContent;
      (document.head || document.documentElement).appendChild(newScript);
    });
  } catch(err) {
    const el = document.getElementById("app") || document.documentElement;
    el.textContent = "Error loading game chunks: " + err.message;
  }
})();
